import docx
from docx.document import Document as _Document
from docx.table import Table
from docx.text.paragraph import Paragraph

SRC = "/home/node/demo/Offer letters/Inbox/Offer letter template.docx"
OUT = "/home/node/demo/Offer letters/Offer_Osei_Amara.docx"

mapping = {
    "{{COMPANY_NAME}}": "Kestrel Analytics Ltd",
    "{{DATE}}": "12 November 2026",
    "{{CANDIDATE_FULL_NAME}}": "Amara Osei",
    "{{STREET_ADDRESS}}": "11 Harborne Road",
    "{{CITY}}": "Birmingham",
    "{{POSTCODE}}": "B15 3BU",
    "{{POSITION}}": "Customer Success Manager",
    "{{CANDIDATE_FIRST_NAME}}": "Amara",
    "{{DEPARTMENT}}": "Customer Success",
    "{{START_DATE}}": "14 December 2026",
    "{{MANAGER_NAME}}": "Ellen Ward",
    "{{BASE_SALARY}}": "52,000",
    "{{PTO_DAYS}}": "25",
    "{{RESPONSE_DEADLINE}}": "19 November 2026",
    "{{APPROVAL_REF}}": "HA-2026-0227",
}


def replace_tokens(p, mapping):
    # Replace placeholders run by run, so existing run formatting survives.
    guard = 0
    while guard < 200:
        guard += 1
        full = "".join(r.text for r in p.runs)
        hit = None
        for tok, val in mapping.items():
            i = full.find(tok)
            if i != -1:
                hit = (tok, val, i)
                break
        if hit is None:
            return
        tok, val, start = hit
        end = start + len(tok)
        pos = 0
        for r in p.runs:
            rlen = len(r.text)
            rstart, rend = pos, pos + rlen
            pos = rend
            if rend <= start or rstart >= end:
                continue
            ls = max(start, rstart) - rstart
            le = min(end, rend) - rstart
            if rstart <= start:
                r.text = r.text[:ls] + val + r.text[le:]
            else:
                r.text = r.text[:ls] + r.text[le:]


def iter_paragraphs(parent):
    # Yields paragraphs in body text, tables (incl. nested), headers and footers.
    if hasattr(parent, "tables"):
        for t in parent.tables:
            yield from iter_table(t)
    for p in getattr(parent, "paragraphs", []):
        yield p


def iter_table(t):
    for row in t.rows:
        for cell in row.cells:
            for p in cell.paragraphs:
                yield p
            for nt in cell.tables:
                yield from iter_table(nt)


doc = docx.Document(SRC)

# Fill every paragraph in body (recursing nested tables) and in header/footer.
for p in iter_paragraphs(doc):
    replace_tokens(p, mapping)
for section in doc.sections:
    for p in section.header.paragraphs:
        replace_tokens(p, mapping)
    for p in section.footer.paragraphs:
        replace_tokens(p, mapping)

# Relocation does not apply: delete the conditional paragraph and its heading.
body_paras = doc.paragraphs
for i, p in enumerate(body_paras):
    if "{{IF_RELOCATION}}" in p.text:
        p._element.getparent().remove(p._element)
        if i > 0 and body_paras[i - 1].text.strip() == "Relocation Assistance:":
            h = body_paras[i - 1]
            h._element.getparent().remove(h._element)
        break

# No sign-on bonus and no equity grant: drop those rows from the inner table.
for outer in doc.tables:
    for row in outer.rows:
        for cell in row.cells:
            for inner in cell.tables:
                for r in list(inner.rows):
                    label = r.cells[0].text.strip()
                    if label in ("Sign-on Bonus:", "Equity Grant:"):
                        r._tr.getparent().remove(r._tr)

# Safety: no placeholder may survive.
leftovers = []
for p in iter_paragraphs(doc):
    if "{{" in p.text:
        leftovers.append(p.text)
for section in doc.sections:
    for p in list(section.header.paragraphs) + list(section.footer.paragraphs):
        if "{{" in p.text:
            leftovers.append(p.text)
assert not leftovers, leftovers

doc.save(OUT)
print("saved", OUT)

